function initPersonalizacionModal(){document.querySelectorAll(".project-image").forEach(e=>{e.addEventListener("click",()=>abrirModal(e))})}function abrirModal(e){const o=document.getElementById("modal");o&&o.remove();const n=document.createElement("div");n.id="modal",n.className="modal",n.style.display="flex",n.innerHTML=`<img id="modal-img" class="modal-content" src="${e.src}" alt="${e.alt||""}">`,n.addEventListener("click",()=>n.remove()),document.body.appendChild(n)}document.addEventListener("keydown",e=>{if("Escape"===e.key){const e=document.getElementById("modal");e&&e.remove()}});export{initPersonalizacionModal};